@tool
extends Node

func _walk(base: String, out: Array) -> void:
	var d := DirAccess.open("res://" + base)
	if d == null:
		return
	d.list_dir_begin()
	var n := d.get_next()
	while n != "":
		if n.begins_with(".") == false:
			var p := (base + "/" + n) if base != "" else n
			if d.current_is_dir():
				_walk(p, out)
			else:
				out.append(p)
		n = d.get_next()
	d.list_dir_end()

func run() -> String:
	var files: Array = []
	_walk("assets/quaternius", files)
	var hits: Array = []
	var glb_count := 0
	var glb_hit := 0
	for f in files:
		var fs := String(f)
		var ext := fs.get_extension().to_lower()
		if ext == "glb" or ext == "gltf":
			if ext == "glb":
				glb_count += 1
			var txt: String = FileAccess.get_file_as_string("res://" + fs)
			if txt.find("textures/T_") != -1 or txt.find("textures/Imp") != -1 or txt.find("textures/Puglin") != -1:
				if ext == "glb":
					glb_hit += 1
				if hits.size() < 25:
					hits.append(fs)
	var rep := {"glb_total": glb_count, "glb_hits": glb_hit, "samples": hits}
	var out := FileAccess.open("res://tools/gc_case_report.json", FileAccess.WRITE)
	if out != null:
		out.store_string(JSON.stringify(rep))
	return "CASE2 glb=" + str(glb_count) + " hits=" + str(hits.size())
